// collectFactArtifacts reads facts/<slug>/facts.ndjson, recovering each stream's
// logical branch from the records (the on-disk slug is lossy), and registers a
// FactsRef on art. Streams are keyed by branch and emitted in branch order.
func collectFactArtifacts(art *brainwire.BrainArtifact, brainDir string) ([]publishArtifact, error) {
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return nil, fmt.Errorf("load facts privacy manifest: %w", err)
	}
	guard, err := loadSessionReadGuard(brainDir, manifest)
	if err != nil {
		return nil, fmt.Errorf("load facts privacy policy: %w", err)
	}
	entries, _, err := readPrivacyDirectory(brainDir, factsDirName, "publish facts")
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("read facts: %w", err)
	}

	dirs := subdirNames(entries)
	sort.Strings(dirs)

	type factStream struct {
		branch string
		data   []byte
	}
	var streams []factStream
	seen := make(map[string]struct{})
	for _, dir := range dirs {
		data, ok, err := readBrainBlob(brainDir, filepath.Join(factsDirName, dir, factsFileName))
		if err != nil {
			return nil, fmt.Errorf("read facts %s: %w", dir, err)
		}
		if !ok {
			continue
		}
		branch, err := firstFactBranch(data)
		if err != nil {
			return nil, fmt.Errorf("read facts %s: %w", dir, err)
		}
		if branch == "" {
			continue
		}
		if _, dup := seen[branch]; dup {
			return nil, fmt.Errorf("read facts %s: duplicate branch stream %q", dir, branch)
		}
		seen[branch] = struct{}{}
		streams = append(streams, factStream{branch: branch, data: data})
	}
	sort.Slice(streams, func(i, j int) bool { return streams[i].branch < streams[j].branch })

	var out []publishArtifact
	for _, stream := range streams {
		// REDACT before the bytes become an artifact. The digest and the manifest
		// ContentRef must describe what actually leaves, so the redaction has to
		// happen ahead of both.
		data, err := redactFactsForEgress(stream.data, guard)
		if err != nil {
			return nil, fmt.Errorf("read facts %s: %w", stream.branch, err)
		}
		rel := factsFileRelPath(stream.branch)
		digest := contentDigest(data)
		art.AddFacts(brainwire.FactsRef{
			Branch:  stream.branch,
			Content: brainwire.ContentRef{Digest: digest, Size: int64(len(data)), MediaType: mediaTypeNDJSON, Path: rel},
		})
		out = append(out, publishArtifact{Kind: brainKindFacts, Ref: stream.branch, Digest: digest, Data: data})
	}
	return out, nil
}

// redactFactsForEgress re-renders a facts stream with the LOCAL-ONLY provenance
// coordinates stripped, which is what `facts sync` has always done and what publish
// did not.
//
// A distilled fact's anchor mixes two kinds of value (see factsync.SanitizeForEgress):
// opaque cross-member ids another member can carry but never resolve (session id,
// commit, checkpoint, turn), and the coordinates of a private file on THIS machine —
// Transcript, a brain-relative transcript path, and Line, a turn offset into it. The
// path is not an opaque handle: it is rendered as
//
//	sessions/main/20260530T174906Z_codex_<session-uuid>_<checkpoint>.jsonl
//

func factTopLevel(path string) string {
	if i := strings.IndexByte(path, '.'); i >= 0 {
		return path[:i]
	}
	return path
}

// --- on-disk layout -------------------------------------------------------

// factsBranchRelDir returns the brain-relative directory holding a branch's
// facts. The readable slug alone is not collision-free — distinct branches can
// sanitize to the same slug (e.g. "evis/search" and "evis-search", or "Main"
// and "main") — and two branches sharing a facts file would clobber each other
// and break branch isolation. A short hash of the full branch name is appended
// so each branch maps to a stable, unique directory while staying greppable.
func factsBranchRelDir(branch string) string {
	slug := safePathComponent(branch, "branch", 80)
	sum := sha256.Sum256([]byte(branch))
	return filepath.ToSlash(filepath.Join(factsDirName, slug+"-"+hex.EncodeToString(sum[:4])))
}

func factsFileRelPath(branch string) string {
	return filepath.ToSlash(filepath.Join(factsBranchRelDir(branch), factsFileName))
}

// factBranchStoreExists reports whether the brain actually holds a facts.ndjson
// for a branch.
//
// loadFacts deliberately returns an empty slice for a missing file so first-run
// callers need no special case, which means every read surface reports a
// misspelled branch exactly as it reports a real branch with nothing on it.
// Wherever that difference matters — naming a promote endpoint, say — this is
// the check that tells the two apart.
func factBranchStoreExists(brainDir, branch string) bool {
	if brainDir == "" || branch == "" {
		return false
	}
	_, err := os.Stat(filepath.Join(brainDir, filepath.FromSlash(factsFileRelPath(branch))))
	return err == nil
}

// loadFacts reads a branch's facts.ndjson. A missing file is not an error: it
// yields an empty slice so first-run callers do not special-case it. Blank
// lines are skipped; a malformed line is a hard error so a corrupt store is
// surfaced rather than silently dropping records.
func loadFacts(brainDir, branch string) ([]factRecord, error) {
	rel := factsFileRelPath(branch)
	if err := rejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
		return nil, err
	}
	path := filepath.Join(brainDir, filepath.FromSlash(rel))
	if info, err := os.Lstat(path); err == nil && !info.Mode().IsRegular() {
		return nil, fmt.Errorf("fact store is not a regular file: %s", rel)
	}
	records, err := parseFactsFile(path)
	if err != nil {
		// The bare parse error names the damage but not the repair, and this
		// is the error every read surface shows a user. Name the repair here,
		// once, the way the history index names `refresh history`.
		// parseFactsFile itself stays clean so the integrity report (which
		// quotes it inside a fuller sentence) does not say it twice.

