func TestPublishRefusesMalformedOrAmbiguousFactStreams(t *testing.T) {
	for _, data := range []string{"not-json\n", "not-json\n{\"branch\":\"main\"}\n", "{}\n", "null\n", "{\"branch\":\"main\"}\n{\"branch\":\"other\"}\n", "{\"branch\":\"main\"}\n{}\n"} {
